//! Regression of native synthetic data, not a user data import path.

use crate::{LadiesCore, Preference};
use std::path::Path;

#[test]
#[ignore = "requires synthetic native v3 DB generated by tools/m05-reference.py; run in CI"]
fn m05_native_reference_fixture() {
    let database = std::env::var("M05_REFERENCE_DB").expect("synthetic native DB path");
    let core = LadiesCore::new(database).unwrap();
    let status = core.status().unwrap();
    assert_eq!(status.schema_version, crate::schema::VERSION);
    assert_eq!(status.person_count, 8);
    assert_eq!(status.listing_count, 9);
    assert_eq!(status.source_profile_count, 8);

    let person = core.get_person(2).unwrap().unwrap();
    assert_eq!(person.preference, Preference::Like);
    assert!(person.favorite);
    let person_one_listing: i64 = {
        let db = core.connection().unwrap();
        db.query_row(
            "SELECT listing_id FROM listings WHERE person_id = 1 ORDER BY listing_id LIMIT 1",
            [],
            |row| row.get(0),
        )
        .unwrap()
    };
    assert_eq!(
        core.person_note(person_one_listing, 1).unwrap().as_deref(),
        Some("Synthetische Personennotiz")
    );
    let media = {
        let db = core.connection().unwrap();
        crate::discovery::media_from(&core, &db, 1011).unwrap()
    };
    assert_eq!(media.len(), 1);
    assert!(Path::new(media[0].local_path.as_ref().unwrap()).is_file());

    let db = core.connection().unwrap();
    for (table, expected) in [
        ("persons", 8),
        ("source_profiles", 8),
        ("listings", 9),
        ("listing_snapshots", 18),
        ("media_assets", 5),
        ("saved_searches", 2),
        ("search_runs", 3),
    ] {
        let actual: i64 = db
            .query_row(&format!("SELECT COUNT(*) FROM {table}"), [], |row| {
                row.get(0)
            })
            .unwrap();
        assert_eq!(actual, expected, "{table}");
    }
    let results: i64 = db
        .query_row(
            "SELECT COUNT(*) FROM search_results WHERE search_run_id = 3",
            [],
            |row| row.get(0),
        )
        .unwrap();
    assert_eq!(results, 7);
    let integrity: String = db
        .query_row("PRAGMA integrity_check", [], |row| row.get(0))
        .unwrap();
    assert_eq!(integrity, "ok");
    assert!(
        !db.prepare("PRAGMA foreign_key_check")
            .unwrap()
            .exists([])
            .unwrap()
    );
}
